
-- load.sql
-- Ygeiopolis Hospital Database - Data Loader (orchestrator)

--
-- This script:
--   1. Cleans existing data (in dependency-safe order)
--   2. Loads REFERENCE data from CSVs via LOAD DATA LOCAL INFILE
--      (icd10, ken, procedures, lab_exams, drugs, substances)
--   3. Sources synthetic_data.sql which contains all synthetic INSERTs
--      (staff, patients, hospitalizations, etc. — generated by
--       code/generate_data.py)
--   4. Verifies row counts
--
-- Prerequisites:
--   - install.sql has been executed (schema + triggers exist)
--   - CSV files exist in ./sql/data/ (UTF-8, comma-delimited, with headers)
--   - synthetic_data.sql has been generated by generate_data.py
--
-- Recommended way to run (from project root):
--   mysql -u <user> -p --local-infile=1 ygeiopolis_db < sql/load.sql
--
-- If LOCAL INFILE is disabled on the server, run on the client:
--   SET GLOBAL local_infile=1;


USE `ygeiopolis_db`;

-- Allow LOCAL INFILE for this session
SET GLOBAL local_infile = 1;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';


-- 0. CLEANUP (reverse dependency order)

SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM `shift_assignment`;
DELETE FROM `shift`;
DELETE FROM `prescription`;
DELETE FROM `patient_allergy`;
DELETE FROM `procedure_participation`;
DELETE FROM `procedure_occurrence`;
DELETE FROM `procedure_room`;
DELETE FROM `lab_exam`;
DELETE FROM `lab_exam_type`;
DELETE FROM `rating`;
DELETE FROM `hospitalization`;
DELETE FROM `triage_record`;
DELETE FROM `patient_contact`;
DELETE FROM `bed`;
DELETE FROM `doctor_department`;
DELETE FROM `admin_staff`;
DELETE FROM `nurse`;
DELETE FROM `department`;
DELETE FROM `doctor`;
DELETE FROM `patient`;
DELETE FROM `staff`;

DELETE FROM `drug_active_substance`;
DELETE FROM `active_substance`;
DELETE FROM `drug`;
DELETE FROM `medical_procedure`;
DELETE FROM `ken`;
DELETE FROM `icd10_diagnosis`;

-- Reset AUTO_INCREMENT counters (CRITICAL for active_substance:
-- generate_data.py assumes substance_id starts from 1)
ALTER TABLE `staff`                   AUTO_INCREMENT = 1;
ALTER TABLE `department`              AUTO_INCREMENT = 1;
ALTER TABLE `bed`                     AUTO_INCREMENT = 1;
ALTER TABLE `patient_contact`         AUTO_INCREMENT = 1;
ALTER TABLE `triage_record`           AUTO_INCREMENT = 1;
ALTER TABLE `hospitalization`         AUTO_INCREMENT = 1;
ALTER TABLE `rating`                  AUTO_INCREMENT = 1;
ALTER TABLE `lab_exam`                AUTO_INCREMENT = 1;
ALTER TABLE `procedure_room`          AUTO_INCREMENT = 1;
ALTER TABLE `procedure_occurrence`    AUTO_INCREMENT = 1;
ALTER TABLE `prescription`            AUTO_INCREMENT = 1;
ALTER TABLE `shift`                   AUTO_INCREMENT = 1;
ALTER TABLE `active_substance`        AUTO_INCREMENT = 1;

SET FOREIGN_KEY_CHECKS = 1;



-- 1. REFERENCE DATA (LOAD DATA LOCAL INFILE)

-- All CSV files:
--   - UTF-8 encoded
--   - Separator: ','
--   - First line is a header (IGNORE 1 LINES)
--   - String fields with commas/quotes are enclosed in double quotes



-- 1.1 ICD-10 diagnoses
-- File: sql/data/icd10.csv  (~11,000 rows)
-- Columns: icd10_code,description

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/icd10.csv'
INTO TABLE `icd10_diagnosis`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`icd10_code`, `description`);


-- 1.2 KEN (Κλειστά Ενοποιημένα Νοσήλια)
-- File: sql/data/ken.csv  (~694 rows)
-- Columns: ken_code,description,base_cost,mean_length_of_stay

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/ken.csv'
INTO TABLE `ken`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`ken_code`, `description`, `base_cost`, `mean_length_of_stay`);


-- 1.3 Medical procedures
-- File: sql/data/procedures.csv  (~6,608 rows)
-- Columns: procedure_code,name,category,duration,cost

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/procedures.csv'
INTO TABLE `medical_procedure`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`procedure_code`, `name`, `category`, `duration`, `cost`);


-- 1.4 Lab Exam Types (Ministry of Health, Categories Γ, Δ, Ε)
-- File: sql/data/lab_exams.csv  (~2,821 rows)
-- Columns: exam_code, exam_name, exam_type
-- Categories:
--   Γ → απεικονιστική  (radiology, imaging)
--   Δ → βιοπαθολογία   (blood, biochemistry, microbiology)
--   Ε → κυτταρολογία   (cytology, pathology, forensics)

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/lab_exams.csv'
INTO TABLE `lab_exam_type`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`exam_code`, `exam_name`, `exam_type`);


-- 1.5 Active substances (EMA Article 57, Greek-authorised)
-- File: sql/data/active_substances.csv  (~1,526 rows)
-- Columns: substance_name
--
-- Note: substance_id is AUTO_INCREMENT — sequential 1..N in CSV order
--       (alphabetical). This sequence MUST match the order of insertion
--       so that generate_data.py's allergy mapping works correctly.

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/active_substances.csv'
INTO TABLE `active_substance`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`substance_name`);


-- 1.6 Drugs (EMA Article 57, Greek-authorised)
-- File: sql/data/drugs.csv  (~4,697 rows)
-- Columns: drug_id,drug_name

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/drugs.csv'
INTO TABLE `drug`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`drug_id`, `drug_name`);


-- 1.7 Drug ↔ Active substance links
-- File: sql/data/drug_active_substance.csv  (~4,860 rows)
-- Columns: drug_id,substance_name
--
-- The CSV holds substance NAMES, but the table holds substance IDs.
-- We resolve names → IDs via a temporary staging table + JOIN.

DROP TEMPORARY TABLE IF EXISTS `tmp_drug_substance`;
CREATE TEMPORARY TABLE `tmp_drug_substance` (
  `drug_id`        VARCHAR(30)  NOT NULL,
  `substance_name` VARCHAR(100) NOT NULL,
  KEY (`drug_id`),
  KEY (`substance_name`)
) ENGINE=InnoDB CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

LOAD DATA LOCAL INFILE 'C:/db_project/hospital_project/sql/data/drug_active_substance.csv'
INTO TABLE `tmp_drug_substance`
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' ESCAPED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(`drug_id`, `substance_name`);

INSERT IGNORE INTO `drug_active_substance` (`drug_id`, `substance_id`)
SELECT t.drug_id, s.substance_id
FROM   `tmp_drug_substance` t
JOIN   `active_substance` s ON s.substance_name = t.substance_name
JOIN   `drug` d             ON d.drug_id        = t.drug_id;

DROP TEMPORARY TABLE `tmp_drug_substance`;



-- 2. SYNTHETIC DATA

-- All synthetic INSERTs are generated by code/generate_data.py
-- and written to sql/synthetic_data.sql
--
-- IMPORTANT: To generate this file, run BEFORE this script:
--   python3 code/generate_data.py --data-dir sql/data --out sql/synthetic_data.sql



-- 2.1 Temporarily drop supervisor triggers so that bulk INSERT
--     of doctors (initially without supervisor_amka) does not fail.
--     generate_data.py inserts all doctors first with supervisor_amka=NULL,
--     then runs UPDATE statements to set supervisors.

DROP TRIGGER IF EXISTS `trg_doctor_insert_rank_supervisor`;
DROP TRIGGER IF EXISTS `trg_doctor_update_rank_supervisor`;

SOURCE C:/db_project/hospital_project/sql/synthetic_data.sql;


-- 2.2 Re-create supervisor triggers after bulk insert

DELIMITER $$

CREATE TRIGGER `trg_doctor_insert_rank_supervisor`
BEFORE INSERT ON `doctor`
FOR EACH ROW
BEGIN
  IF NEW.rank = 'Ειδικευόμενος' AND NEW.supervisor_amka IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Ειδικευόμενος ιατρός πρέπει να έχει επόπτη.';
  END IF;
  IF NEW.rank = 'Διευθυντής' AND NEW.supervisor_amka IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Διευθυντής δεν μπορεί να έχει επόπτη.';
  END IF;
END$$

CREATE TRIGGER `trg_doctor_update_rank_supervisor`
BEFORE UPDATE ON `doctor`
FOR EACH ROW
BEGIN
  IF NEW.rank = 'Ειδικευόμενος' AND NEW.supervisor_amka IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Ειδικευόμενος ιατρός πρέπει να έχει επόπτη.';
  END IF;
  IF NEW.rank = 'Διευθυντής' AND NEW.supervisor_amka IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Διευθυντής δεν μπορεί να έχει επόπτη.';
  END IF;
END$$

DELIMITER ;



-- 3. VERIFICATION

-- Print row counts for a quick sanity check after loading.


SELECT 'icd10_diagnosis'         AS table_name, COUNT(*) AS row_count FROM `icd10_diagnosis`
UNION ALL SELECT 'ken',                         COUNT(*) FROM `ken`
UNION ALL SELECT 'medical_procedure',           COUNT(*) FROM `medical_procedure`
UNION ALL SELECT 'lab_exam_type',               COUNT(*) FROM `lab_exam_type`
UNION ALL SELECT 'active_substance',            COUNT(*) FROM `active_substance`
UNION ALL SELECT 'drug',                        COUNT(*) FROM `drug`
UNION ALL SELECT 'drug_active_substance',       COUNT(*) FROM `drug_active_substance`
UNION ALL SELECT 'staff',                       COUNT(*) FROM `staff`
UNION ALL SELECT 'doctor',                      COUNT(*) FROM `doctor`
UNION ALL SELECT 'nurse',                       COUNT(*) FROM `nurse`
UNION ALL SELECT 'admin_staff',                 COUNT(*) FROM `admin_staff`
UNION ALL SELECT 'department',                  COUNT(*) FROM `department`
UNION ALL SELECT 'doctor_department',           COUNT(*) FROM `doctor_department`
UNION ALL SELECT 'bed',                         COUNT(*) FROM `bed`
UNION ALL SELECT 'patient',                     COUNT(*) FROM `patient`
UNION ALL SELECT 'patient_contact',             COUNT(*) FROM `patient_contact`
UNION ALL SELECT 'patient_allergy',             COUNT(*) FROM `patient_allergy`
UNION ALL SELECT 'triage_record',               COUNT(*) FROM `triage_record`
UNION ALL SELECT 'hospitalization',             COUNT(*) FROM `hospitalization`
UNION ALL SELECT 'rating',                      COUNT(*) FROM `rating`
UNION ALL SELECT 'lab_exam',                    COUNT(*) FROM `lab_exam`
UNION ALL SELECT 'procedure_room',              COUNT(*) FROM `procedure_room`
UNION ALL SELECT 'procedure_occurrence',        COUNT(*) FROM `procedure_occurrence`
UNION ALL SELECT 'procedure_participation',     COUNT(*) FROM `procedure_participation`
UNION ALL SELECT 'prescription',               COUNT(*) FROM `prescription`
UNION ALL SELECT 'shift',                       COUNT(*) FROM `shift`
UNION ALL SELECT 'shift_assignment',            COUNT(*) FROM `shift_assignment`;

-- end of load.sql
